    for gene_name in self.search_space:
        possible_values = self.search_space[gene_name]
        if gene_name == 'dropout_prob':
            # Ensure dropout_prob is always greater than 0.0
            possible_values = [p for p in possible_values if p > 0.0]

        # Calculate weights based on gene frequency
        weights = [self.gene_frequency.get(gene_name, {}).get(value, 1) for value in possible_values]
        total_weight = sum(weights)
        cumulative_weights = [sum(weights[:i+1]) for i in range(len(weights))]

        # Select a value based on weighted probabilities
        rand_val = random.random() * total_weight
        selected_idx = bisect.bisect_left(cumulative_weights, rand_val)
        selected_value = possible_values[selected_idx]

        # Apply a small mutation to introduce diversity
        if random.random() < 0.1:
            if selected_value == possible_values[0]:
                selected_value = possible_values[1]
            elif selected_value == possible_values[-1]:
                selected_value = possible_values[-2]
            else:
                selected_value = random.choice([possible_values[possible_values.index(selected_value) - 1], possible_values[possible_values.index(selected_value) + 1]])

        chromosome[gene_name] = selected_value

    return chromosome
